### 📌 C++ コード（コメント付き） - 300行以内

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <chrono>
#include <sstream>
#include <algorithm>
#include <map>
#include <ctime>
#include <filesystem>

using namespace std;

// パラメータ設定
const string DATA_DIR = "/data/customer_logs"; // データが保存されているディレクトリ
const string DB_URI = "postgresql://user:password@localhost:5432/customer_db"; // データベース接続情報
const int THREAD_COUNT = 4; // マルチスレッドのスレッド数

mutex mtx; // ロックオブジェクト：マルチスレッドで共有変数の競合を防ぐ
int processed = 0; // 処理済みファイル数
int total_files = 0; // 総ファイル数

/**
 * テキストのクリーニング：特殊文字を削除、小文字化、単語の分割
 * @param text: 変更したいテキスト
 */
void cleanText(string& text) {
    // 特殊文字を削除（アルファベット、数字、スペース以外は削除）
    text.erase(remove_if(text.begin(), text.end(), 
                         [](char c) { return !isalnum(c) && !isspace(c); }), text.end());
    // テキストをすべて小文字に変換
    transform(text.begin(), text.end(), text.begin(), ::tolower);
}

/**
 * データの前処理：重複を削除、ソート
 * @param data: プロセス対象のデータ（テキストのベクトル）
 */
void preprocess(vector<string>& data) {
    // データをソート
    sort(data.begin(), data.end());
    // 重複を削除
    data.erase(unique(data.begin(), data.end()), data.end());
}

/**
 * サポートチャットの分析（仮の実装）
 * @param chats: チャットテキストのベクトル
 * @param queryTypes: 問い合わせタイプのカウント（map）
 * @param sentiments: 感情スコアのベクトル
 */
void analyzeSupport(vector<string>& chats, map<string, int>& queryTypes, vector<double>& sentiments) {
    // 仮の感情分析（実際にはNLPライブラリが必要）
    for (auto& chat : chats) {
        sentiments.push_back(0.5); // 仮の感情スコア（0.0〜1.0）
    }
    // 仮の問い合わせタイプのカウント
    for (auto& chat : chats) {
        string type = "general"; // 仮のタイプ（実際には分類モデルで判定）
        queryTypes[type]++;
    }
}

/**
 * ファイルを処理し、分析結果を保存
 * @param file: ファイルパス
 * @param type: ファイルタイプ（CSVまたはJSON）
 */
void processFile(const string& file, const string& type) {
    try {
        ifstream f(file); // ファイルを開く
        string line;
        vector<string> data; // データを保存するベクトル
        while (getline(f, line)) {
            data.push_back(line); // ファイルの各行を読み込む
        }
        preprocess(data); // データの前処理
        map<string, int> queryTypes;
        vector<double> sentiments;
        analyzeSupport(data, queryTypes, sentiments); // 分析処理
        cout << "Processed: " << file << endl; // 処理完了メッセージ
        lock_guard<mutex> lock(mtx); // ロックを取得
        processed++; // 処理済みファイル数をインクリメント
    } catch (...) {
        cerr << "Error processing " << file << endl; // エラー処理
    }
}

/**
 * リアルタイムの処理進捗を表示
 */
void monitorProgress() {
    while (processed < total_files) {
        this_thread::sleep_for(chrono::seconds(1)); // 1秒ごとにチェック
        lock_guard<mutex> lock(mtx); // ロックを取得
        cout << "\rProcessing: " << processed << "/" << total_files << " files" << flush;
    }
    cout << "\nProcessing complete!" << endl; // 処理終了メッセージ
}

/**
 * メイン処理：すべての処理を開始
 */
int main() {
    vector<string> files; // 処理するファイルのリスト
    for (const auto& entry : filesystem::directory_iterator(DATA_DIR)) {
        // CSVまたはJSONファイルのみを処理
        if (entry.path().extension() == ".csv" || entry.path().extension() == ".json") {
            files.push_back(entry.path().string());
            total_files++; // 総ファイル数をカウント
        }
    }

    thread monitor(monitorProgress); // 進捗表示スレッドを起動
    vector<thread> threads; // スレッドのベクトル
    for (int i = 0; i < min(THREAD_COUNT, (int)files.size()); ++i) {
        threads.emplace_back(processFile, files[i], "csv"); // ファイルを処理するスレッドを起動
    }

    for (auto& t : threads) t.join(); // タスクを待機
    monitor.join(); // 進捗表示スレッドを待機

    return 0;
}
```

---

### 📌 コードのコメントの要点

| 関数名 | コメントの主な内容 |
|--------|------------------|
| `cleanText` | 特殊文字の削除、小文字化、テキストの標準化 |
| `preprocess` | 重複の削除、ソート、データの前処理 |
| `analyzeSupport` | 仮の感情分析、問い合わせタイプのカウント |
| `processFile` | ファイルの読み込み、処理、エラーハンドリング |
| `monitorProgress` | リアルタイム進捗の表示 |
| `main` | メイン処理：ファイルのスキャン、スレッドの起動、処理の実行 |

