/**
 * Cleans text by removing special characters and converting to lowercase.
 * @param text The input text to clean.
 * @return Cleaned text.
 */
string cleanText(const string& text) {
    regex pattern("[^a-zA-Z0-9\\s]"); // Regex pattern to match non-alphanumeric and non-space characters
    return regex_replace(text, pattern, ""); // Replace matched characters with empty string
}

/**
 * Standardizes time format using strptime.
 * @param timestamp Input timestamp string.
 * @return Pointer to tm struct if valid, else null.
 */
tm* standardizeTime(const string& timestamp) {
    tm* timeinfo = new tm{}; // Create a new tm struct
    strptime(timestamp.c_str(), "%Y-%m-%d %H:%M:%S", timeinfo); // Parse timestamp
    return timeinfo; // Return the parsed time struct
}

/**
 * Removes duplicate entries from a list of strings.
 * @param data Vector of strings to deduplicate.
 * @return Vector of unique strings.
 */
vector<string> removeDuplicates(const vector<string>& data) {
    set<string> seen; // Set to track seen items
    vector<string> result; // Result vector
    for (const auto& item : data) {
        if (seen.find(item) == seen.end()) { // If item not seen
            seen.insert(item); // Add to set
            result.push_back(item); // Add to result
        }
    }
    return result; // Return unique items
}

